package com.app.entity; import jakarta.persistence.*; import lombok.*; import java.time.*;
@Entity @Table(name="society_attendance_sheets") @Data @Builder @NoArgsConstructor @AllArgsConstructor public class SocietyAttendanceSheet {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="account_id",nullable=false) private Account account;@Column(nullable=false) private LocalDate attendanceDate;@Column(nullable=false) @Builder.Default private String status="DRAFT";@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="submitted_by_user_id") private User submittedBy;private LocalDateTime submittedAt;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="locked_by_user_id") private User lockedBy;private LocalDateTime lockedAt;@Column(nullable=false) @Builder.Default private LocalDateTime updatedAt=LocalDateTime.now();@PreUpdate void touch(){updatedAt=LocalDateTime.now();}}
